using System;
using System.Collections.Generic;
using System.IO;
using CoreAI.Ai;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace CoreAI.Core.Tests.EditMode
{
    /// <summary>
    /// A skill written as ONE text with <c>&lt;!-- section: name --&gt;</c> lines (the form the built-in
    /// skills ship in, generated by <c>tools/generate_skills.py</c>) keeps its sections addressable when it is
    /// loaded through <see cref="SkillSet.FromTextContent"/> or <see cref="SkillSet.FromFile"/>; a text without
    /// markers stays one document, byte for byte.
    /// </summary>
    public sealed class SkillSectionMarkupEditModeTests
    {
        private const string Marked =
            "<!-- section: core -->\n# Core\nCORE_BODY\n\n## A heading inside the core\nmore core\n\n" +
            "<!-- section: terrain -->\n# Terrain\nTERRAIN_BODY\n\n" +
            "<!-- section: uxml -->\n# UXML\nUXML_BODY\n";

        private static SkillSet Load(string text, params ILlmTool[] tools)
        {
            return SkillSet.FromTextContent("Rbx API", "Roblox API", text, tools);
        }

        private static JObject Read(SkillSet skill, string section = null, bool all = false)
        {
            return JObject.Parse(ReadSkillLlmTool.ReadSkillJson(new[] { skill }, skill.Name, section, all));
        }

        [Test]
        public void MarkedText_SplitsIntoOrderedSections_AndKeepsInnerHeadings()
        {
            SkillSet skill = Load(Marked);

            Assert.AreEqual(3, skill.Sections.Count);
            Assert.AreEqual("core", skill.Sections[0].Name, "the first section is the entry document");
            Assert.AreEqual("# Core\nCORE_BODY\n\n## A heading inside the core\nmore core", skill.Sections[0].Content);
            Assert.IsTrue(skill.TryGetSection("TERRAIN", out SkillSection terrain));
            Assert.AreEqual("# Terrain\nTERRAIN_BODY", terrain.Content);
            Assert.AreEqual("uxml", skill.Sections[2].Name);
        }

        [Test]
        public void UnmarkedText_StaysOneDocument_ByteForByte()
        {
            const string legacy = "# CoreAI Rbx API Reference\n\n## 1. Space & rules\n- studs\r\n## 2. Datatypes\n";

            SkillSet skill = Load(legacy);

            Assert.AreEqual(1, skill.Sections.Count, "a host override without markers is the old single document");
            Assert.AreEqual(legacy, skill.Instructions);
            Assert.IsNull(SkillSet.ParseSectionMarkup(legacy));
            Assert.IsNull(SkillSet.ParseSectionMarkup(null));
        }

        [Test]
        public void CrlfText_ParsesLikeLf()
        {
            SkillSet lf = Load(Marked);
            SkillSet crlf = Load(Marked.Replace("\n", "\r\n"));

            Assert.AreEqual(lf.Sections.Count, crlf.Sections.Count);
            for (int i = 0; i < lf.Sections.Count; i++)
            {
                Assert.AreEqual(lf.Sections[i].Name, crlf.Sections[i].Name);
                Assert.AreEqual(lf.Sections[i].Content, crlf.Sections[i].Content);
            }
        }

        [Test]
        public void TextBeforeTheFirstMarker_BelongsToTheEntryDocument()
        {
            SkillSet skill = Load("PREFACE\n" + Marked);

            StringAssert.StartsWith("PREFACE\n# Core", skill.Sections[0].Content);
            Assert.AreEqual(3, skill.Sections.Count);
        }

        [Test]
        public void FormatSectionMarker_IsTheLineTheParserReads()
        {
            Assert.AreEqual("<!-- section: terrain -->", SkillSet.FormatSectionMarker("terrain"));

            IReadOnlyList<KeyValuePair<string, string>> parts = SkillSet.ParseSectionMarkup(
                SkillSet.FormatSectionMarker("entry") + "\nE\n" + SkillSet.FormatSectionMarker("more") + "\nM\n");

            Assert.AreEqual(2, parts.Count);
            Assert.AreEqual("entry", parts[0].Key);
            Assert.AreEqual("E", parts[0].Value);
            Assert.AreEqual("more", parts[1].Key);
            Assert.AreEqual("M", parts[1].Value);
        }

        [TestCase("<!-- section: core -->\nA\n<!-- section: core -->\nB\n")]
        [TestCase("<!-- section: core -->\nA\n<!-- section: ../secret -->\nB\n")]
        [TestCase("<!-- section: -->\nA\n")]
        public void MalformedMarkers_AreRefusedLoudly(string text)
        {
            Assert.Throws<ArgumentException>(() => Load(text),
                "a duplicate, escaping or empty section name must not silently drop a section");
        }

        [Test]
        public void FromFile_ReadsMarkedTextIntoSections()
        {
            string path = Path.Combine(Path.GetTempPath(), "coreai-marked-skill-" + Guid.NewGuid().ToString("N") + ".txt");
            try
            {
                File.WriteAllText(path, Marked);
                SkillSet skill = SkillSet.FromFile("Rbx API", "Roblox API", path);
                Assert.AreEqual(3, skill.Sections.Count);
                Assert.IsTrue(skill.TryGetSection("uxml", out SkillSection uxml));
                Assert.AreEqual("# UXML\nUXML_BODY", uxml.Content);
            }
            finally
            {
                if (File.Exists(path))
                {
                    File.Delete(path);
                }
            }
        }

        [Test]
        public void BareRead_ReturnsOnlyTheEntryAndTheOtherNames()
        {
            JObject result = Read(Load(Marked));

            Assert.IsTrue(result.Value<bool>("success"));
            Assert.AreEqual("core", result.Value<string>("section"));
            StringAssert.Contains("CORE_BODY", result.Value<string>("instructions"));
            StringAssert.DoesNotContain("TERRAIN_BODY", result.Value<string>("instructions"));
            CollectionAssert.AreEqual(new[] { "terrain", "uxml" }, result["sections"].ToObject<string[]>());
        }

        [Test]
        public void InstructionsOnlySectionedSkill_UsageDoesNotAdvertiseCallSkillTool()
        {
            SkillSet skill = Load(Marked);

            string bareUsage = Read(skill).Value<string>("usage");
            string sectionUsage = Read(skill, "terrain").Value<string>("usage");

            StringAssert.DoesNotContain("call_skill_tool", bareUsage, "a skill without tools has nothing to call");
            StringAssert.Contains("read_skill(skill_name, section)", bareUsage);
            StringAssert.DoesNotContain("call_skill_tool", sectionUsage);
            StringAssert.Contains("read_skill(skill_name)", sectionUsage);
        }

        [Test]
        public void SectionedSkillWithTools_KeepsTheCallSkillToolUsage()
        {
            DelegateLlmTool tool = new("place_block", "Places a block.", new Action(() => { }));
            SkillSet skill = Load(Marked, tool);

            StringAssert.Contains("call_skill_tool", Read(skill).Value<string>("usage"),
                "negative twin: a skill with tools still explains how to call them");
            StringAssert.Contains("call_skill_tool", Read(skill, "terrain").Value<string>("usage"));
        }

        [Test]
        public void SingleDocumentSkill_UsageIsUnchanged()
        {
            JObject result = Read(SkillSet.FromTextContent("Plain", "One document", "THE BODY"));

            StringAssert.StartsWith("Call call_skill_tool(tool_name, arguments_json)", result.Value<string>("usage"),
                "the staging must not change what an existing one-document skill returns");
            Assert.IsNull(result["sections"]);
        }

        [Test]
        public void ReadAll_ReturnsEverySectionUnderItsName()
        {
            JObject all = Read(Load(Marked), all: true);

            string instructions = all.Value<string>("instructions");
            StringAssert.Contains("## core\n# Core", instructions);
            StringAssert.Contains("## terrain\n# Terrain\nTERRAIN_BODY", instructions);
            StringAssert.DoesNotContain("<!-- section:", instructions, "the markers are a storage form, not text");
        }
    }
}
